/**
 * Stand-in for the real semantic-search Python microservice
 * (apps/semantic-search/app/engine.py), reached over HTTP in production via
 * apps/backend/src/modules/semantic-search/client.ts.
 *
 * Post-refactor, the real service returns ONLY lightweight identifiers
 * (subject + courseNumber) -- title/description/score/text were stripped
 * because nothing downstream needs them once the backend hydrates from its
 * own cache. This mock mirrors that: it returns a ranked list of class ids
 * and nothing else. There is no network call here -- it's a synchronous
 * lookup against a fixed table of canned query -> ranking results, which is
 * enough to model "an external service that only knows how to rank, not
 * hydrate."
 *
 * Do not add title/description/etc. back onto this return type -- that
 * would defeat the point of the exercise (the whole reason a hydration step
 * is needed at all is that the ranking service intentionally returns only
 * identifiers).
 */
const RANKINGS: Record<string, string[]> = {
  // All three ids are warm in catalogCache -- the "happy path" query.
  "intro to programming": [
    "COMPSCI-61A-001",
    "COMPSCI-61A-002",
    "COMPSCI-10-001",
  ],

  // STAT-134-001 is NOT in catalogCache (see catalogCache.ts) -- this query
  // exercises the genuine cache-miss fallback path.
  "probability theory": ["STAT-134-001", "COMPSCI-70-001"],

  // COMPSCI-999-001 doesn't exist anywhere -- not in the cache, not in the
  // "database" either (e.g. the class was pulled/cancelled after the
  // semantic index was last built). A correct implementation drops it from
  // the results instead of throwing or returning a hole.
  "web development": ["COMPSCI-169-001", "COMPSCI-999-001"],

  // No matches above the similarity threshold.
  "medieval basket weaving": [],
};

export const semanticSearchService = {
  rank(query: string): string[] {
    return RANKINGS[query.toLowerCase().trim()] ?? [];
  },
};
